import { Inbox, type LucideProps } from 'lucide-react-native';
import type { ComponentType, ReactNode } from 'react';
import { View } from 'react-native';

import { Icon } from '@/components/ui/icon';
import { Text } from '@/components/ui/text';

export function EmptyState({
  title,
  description,
  icon = Inbox,
  action,
}: {
  title: string;
  description?: string;
  icon?: ComponentType<LucideProps>;
  action?: ReactNode;
}) {
  return (
    <View className="flex-1 items-center justify-center gap-3 px-8 py-12">
      <Icon as={icon} className="text-muted-foreground" size={40} />
      <Text className="text-center text-xl font-semibold">{title}</Text>
      {description ? (
        <Text variant="muted" className="text-center">
          {description}
        </Text>
      ) : null}
      {action}
    </View>
  );
}
